// Undirected weighted graph with insertion-ordered adjacency,
// mirroring networkx.Graph semantics (last-write-wins on duplicate edges).

export class Graph {
  constructor() {
    // Map<node, Map<neighbor, {weight: number}>>
    this.adj = new Map();
  }

  addNode(n) {
    if (!this.adj.has(n)) {
      this.adj.set(n, new Map());
    }
  }

  addWeightedEdge(u, v, weight) {
    this.addNode(u);
    this.addNode(v);
    this.adj.get(u).set(v, { weight });
    this.adj.get(v).set(u, { weight });
  }

  addWeightedEdgesFrom(edgeList) {
    for (const [u, v, w] of edgeList) {
      this.addWeightedEdge(u, v, w);
    }
  }

  nodes() {
    return [...this.adj.keys()];
  }

  neighbors(n) {
    return [...this.adj.get(n).keys()];
  }

  hasEdge(u, v) {
    return this.adj.has(u) && this.adj.get(u).has(v);
  }

  getWeight(u, v) {
    return this.adj.get(u).get(v).weight;
  }

  numberOfEdges() {
    let sum = 0;
    let selfLoops = 0;
    for (const [n, nbrs] of this.adj) {
      sum += nbrs.size;
      if (nbrs.has(n)) selfLoops += 1;
    }
    // A self-loop is stored once in the adjacency but contributes 2 to the degree.
    return (sum + selfLoops) / 2;
  }

  // Each undirected edge yielded exactly once, in networkx edges() order:
  // nodes in insertion order, neighbors in insertion order, skipping
  // edges to nodes already processed.
  edges() {
    const result = [];
    const seen = new Set();
    for (const [n, nbrs] of this.adj) {
      for (const [nbr, data] of nbrs) {
        if (!seen.has(nbr)) {
          result.push([n, nbr, data.weight]);
        }
      }
      seen.add(n);
    }
    return result;
  }
}

// Kruskal minimum spanning tree, mirroring nx.minimum_spanning_tree:
// edges sorted by weight (stable), union-find cycle detection.

import { Graph } from './graph.mjs';

export function minimumSpanningTree(G) {
  const edges = G.edges();
  // Array.prototype.sort is stable in modern JS, matching Python's sorted().
  edges.sort((e1, e2) => e1[2] - e2[2]);

  const parent = new Map();
  const find = (x) => {
    while (parent.get(x) !== x) {
      parent.set(x, parent.get(parent.get(x)));
      x = parent.get(x);
    }
    return x;
  };

  const mst = new Graph();
  for (const [u, v, w] of edges) {
    if (!parent.has(u)) parent.set(u, u);
    if (!parent.has(v)) parent.set(v, v);
    const ru = find(u);
    const rv = find(v);
    if (ru !== rv) {
      parent.set(ru, rv);
      mst.addWeightedEdge(u, v, w);
    }
    // ru === rv (including self-loops) would close a cycle: skipped.
  }
  return mst;
}

// Dijkstra shortest path, faithful port of networkx's
// single_source_dijkstra / dijkstra_path / dijkstra_path_length behavior.

// Binary min-heap ordered by (distance, insertion counter).
class Heap {
  constructor() {
    this.items = [];
  }

  push(item) {
    this.items.push(item);
    let i = this.items.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this._less(this.items[i], this.items[p])) {
        [this.items[i], this.items[p]] = [this.items[p], this.items[i]];
        i = p;
      } else {
        break;
      }
    }
  }

  pop() {
    const top = this.items[0];
    const last = this.items.pop();
    if (this.items.length > 0) {
      this.items[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let smallest = i;
        if (l < this.items.length && this._less(this.items[l], this.items[smallest])) smallest = l;
        if (r < this.items.length && this._less(this.items[r], this.items[smallest])) smallest = r;
        if (smallest === i) break;
        [this.items[i], this.items[smallest]] = [this.items[smallest], this.items[i]];
        i = smallest;
      }
    }
    return top;
  }

  _less(a, b) {
    if (a[0] !== b[0]) return a[0] < b[0];
    return a[1] < b[1];
  }

  get size() {
    return this.items.length;
  }
}

function singleSourceDijkstra(G, source, target) {
  const dist = new Map(); // node -> final distance
  const seen = new Map(); // node -> tentative distance
  const paths = new Map([[source, [source]]]);
  const fringe = new Heap();
  let count = 0;

  seen.set(source, 0);
  fringe.push([0, count++, source]);

  while (fringe.size > 0) {
    const [, , v] = fringe.pop();
    if (dist.has(v)) continue;
    dist.set(v, seen.get(v));
    if (v === target) break;
    for (const [u, data] of G.adj.get(v)) {
      const cost = data.weight;
      const vuDist = dist.get(v) + cost;
      if (dist.has(u)) {
        continue;
      } else if (seen.has(u)) {
        if (vuDist < seen.get(u)) {
          seen.set(u, vuDist);
          fringe.push([vuDist, count++, u]);
          paths.set(u, [...paths.get(v), u]);
        }
      } else {
        seen.set(u, vuDist);
        fringe.push([vuDist, count++, u]);
        paths.set(u, [...paths.get(v), u]);
      }
    }
  }
  return { dist, paths };
}

export function dijkstraPath(G, source, target) {
  const { paths } = singleSourceDijkstra(G, source, target);
  if (!paths.has(target)) {
    throw new Error(`No path between ${source} and ${target}.`);
  }
  return paths.get(target);
}

// Returns { value, isFloat }: networkx yields int 0 when source === target
// (no edge weights are ever added), otherwise a float sum of weights.
export function dijkstraPathLength(G, source, target) {
  const { dist } = singleSourceDijkstra(G, source, target);
  if (!dist.has(target)) {
    throw new Error(`No path between ${source} and ${target}.`);
  }
  return { value: dist.get(target), isFloat: source !== target };
}

// BFS / DFS edge generators, mirroring nx.bfs_edges and nx.dfs_edges.
// Neighbors are visited in adjacency insertion order.

export function* bfsEdges(G, source) {
  const visited = new Set([source]);
  // Queue of [parent, neighborIterator]; index-based to allow in-place iteration.
  const queue = [[source, G.neighbors(source)[Symbol.iterator]()]];
  let head = 0;
  while (head < queue.length) {
    const [parent, it] = queue[head];
    const { value: child, done } = it.next();
    if (done) {
      head++;
      continue;
    }
    if (!visited.has(child)) {
      visited.add(child);
      queue.push([child, G.neighbors(child)[Symbol.iterator]()]);
      yield [parent, child];
    }
  }
}

export function* dfsEdges(G, source) {
  const visited = new Set();
  if (visited.has(source)) return;
  visited.add(source);
  const stack = [[source, G.neighbors(source)[Symbol.iterator]()]];
  while (stack.length > 0) {
    const [parent, it] = stack[stack.length - 1];
    const { value: child, done } = it.next();
    if (done) {
      stack.pop();
      continue;
    }
    if (!visited.has(child)) {
      yield [parent, child];
      visited.add(child);
      stack.push([child, G.neighbors(child)[Symbol.iterator]()]);
    }
  }
}

// Node connectivity: minimum size of a node set whose removal leaves the
// graph disconnected or with at most one node. The graphs here are tiny
// (<= 5 distinct nodes), so an exhaustive subset search matches
// nx.node_connectivity exactly (including kappa(K_n) = n - 1).

function* combinations(items, k, start = 0, prefix = []) {
  if (prefix.length === k) {
    yield prefix;
    return;
  }
  for (let i = start; i <= items.length - (k - prefix.length); i++) {
    yield* combinations(items, k, i + 1, [...prefix, items[i]]);
  }
}

function isConnectedOn(G, allowed) {
  if (allowed.size <= 1) return true;
  const start = allowed.values().next().value;
  const seen = new Set([start]);
  const stack = [start];
  while (stack.length > 0) {
    const v = stack.pop();
    for (const u of G.neighbors(v)) {
      if (allowed.has(u) && !seen.has(u)) {
        seen.add(u);
        stack.push(u);
      }
    }
  }
  return seen.size === allowed.size;
}

export function nodeConnectivity(G) {
  const nodes = G.nodes();
  const n = nodes.length;
  for (let k = 0; k <= n - 1; k++) {
    for (const subset of combinations(nodes, k)) {
      const removed = new Set(subset);
      const remaining = new Set(nodes.filter((x) => !removed.has(x)));
      if (remaining.size <= 1) return k;
      if (!isConnectedOn(G, remaining)) return k;
    }
  }
  return n - 1;
}

