// Node connectivity, mirroring nx.node_connectivity's global algorithm
// (Esfahanian's algorithm as implemented in networkx):
//   v = node with minimum degree (self-loops count 2)
//   K = deg(v)
//   K = min(K, local_node_connectivity(v, w)) for every non-neighbor w of v
//   K = min(K, local_node_connectivity(x, y)) for every non-adjacent pair
//       x, y among the neighbors of v
// The graphs here are tiny (<= 5 nodes), so local node connectivity is
// computed by exhaustive cut-set search instead of max-flow; the results
// are identical for non-adjacent node pairs.

function* combinations(items, k, start = 0, prefix = []) {
  if (prefix.length === k) {
    yield prefix;
    return;
  }
  for (let i = start; i <= items.length - (k - prefix.length); i++) {
    yield* combinations(items, k, i + 1, [...prefix, items[i]]);
  }
}

function isConnected(G, excluded = new Set()) {
  const nodes = G.nodes().filter((n) => !excluded.has(n));
  if (nodes.length <= 1) return true;
  const seen = new Set([nodes[0]]);
  const stack = [nodes[0]];
  while (stack.length > 0) {
    const v = stack.pop();
    for (const u of G.neighbors(v)) {
      if (!excluded.has(u) && !seen.has(u)) {
        seen.add(u);
        stack.push(u);
      }
    }
  }
  return seen.size === nodes.length;
}

function hasPath(G, s, t, excluded) {
  const seen = new Set([s]);
  const stack = [s];
  while (stack.length > 0) {
    const v = stack.pop();
    if (v === t) return true;
    for (const u of G.neighbors(v)) {
      if (!excluded.has(u) && !seen.has(u)) {
        seen.add(u);
        stack.push(u);
      }
    }
  }
  return false;
}

// Minimum number of nodes (excluding s and t) whose removal disconnects
// s from t. Only used for non-adjacent pairs, as in networkx's algorithm.
function localNodeConnectivity(G, s, t) {
  const others = G.nodes().filter((n) => n !== s && n !== t);
  for (let k = 0; k <= others.length; k++) {
    for (const subset of combinations(others, k)) {
      if (!hasPath(G, s, t, new Set(subset))) return k;
    }
  }
  return others.length;
}

export function nodeConnectivity(G) {
  const nodes = G.nodes();
  if (!isConnected(G)) return 0;

  // Degree counting a self-loop twice, as networkx's degree does.
  const degree = (n) => {
    let d = 0;
    for (const nbr of G.adj.get(n).keys()) {
      d += nbr === n ? 2 : 1;
    }
    return d;
  };

  // Python's min() keeps the first minimal element in iteration order.
  let v = nodes[0];
  for (const n of nodes) {
    if (degree(n) < degree(v)) v = n;
  }

  let K = degree(v);
  const Nv = G.neighbors(v); // includes v itself when v has a self-loop
  const NvSet = new Set(Nv);

  // Local node connectivity between v and each of its non-neighbors.
  for (const w of nodes) {
    if (w !== v && !NvSet.has(w)) {
      K = Math.min(K, localNodeConnectivity(G, v, w));
    }
  }

  // Local node connectivity between non-adjacent pairs of neighbors of v.
  for (const [x, y] of combinations(Nv, 2)) {
    if (!G.hasEdge(x, y)) {
      K = Math.min(K, localNodeConnectivity(G, x, y));
    }
  }
  return K;
}
